import os
import re

import numpy as np
from .utils import format_str
from ..ir.transform import find_func_in_module
from ..utils import get_func_inputs_outputs

header = """
//=============================================================================
// Auto generated by Allo
//=============================================================================

#include <iostream>
#include <fstream>
#include <vector>
#include <iomanip>
#include <cstring>
#include <cstdlib>

// Catapult HLS headers
#include <ac_int.h>
#include <ac_fixed.h>
#include <ac_channel.h>

#include "kernel.h"

using namespace std;
"""

main_header = """
int main(int argc, char** argv) {
"""

dtype_size_map = {
    "int8": 1,
    "int16": 2,
    "int32": 4,
    "int64": 8,
    "uint8": 1,
    "uint16": 2,
    "uint32": 4,
    "uint64": 8,
    "float16": 2,
    "float32": 4,
    "float64": 8,
}

ctype_map = {
    "bf16": "std::bfloat16_t",
    "f32": "float",
    "f64": "double",
    "i8": "int8_t",
    "i16": "int16_t",
    "i32": "int32_t",
    "i64": "int64_t",
    "ui1": "bool",
    "ui8": "uint8_t",
    "ui16": "uint16_t",
    "ui32": "uint32_t",
    "ui64": "uint64_t",
}


def codegen_host(top, module):
    """Generate C++ host code for Catapult HLS functional simulation.

    Parameters
    ----------
    top : str
        Top-level function name
    module : Module
        MLIR module containing the function
    """
    func = find_func_in_module(module, top)
    inputs, outputs = get_func_inputs_outputs(func)

    out_str = format_str(header, indent=0, strip=False)
    out_str += format_str(main_header, indent=0, strip=False)

    # Process inputs
    for i, (in_dtype, in_shape) in enumerate(inputs):
        # Read from file (text mode)
        out_str += format_str(f'ifstream ifile{i}("input{i}.data");', 4)
        out_str += format_str(f"if (!ifile{i}.is_open()) {{", 4)
        out_str += format_str('cerr << "Error: Could not open input file.\\n";', 8)
        out_str += format_str("return 1;", 8)
        out_str += format_str("}", 4)

        size = np.prod(in_shape) if len(in_shape) > 0 else 1

        # Buffer allocation
        if len(in_shape) == 0:  # Scalar
            scalar_type = ctype_map.get(str(in_dtype), "int")
            out_str += format_str(f"{scalar_type} source_in{i};", 4)
            out_str += format_str(f"ifile{i} >> source_in{i};", 4)
        else:  # Array
            c_type = ctype_map.get(str(in_dtype), "int")
            out_str += format_str(f"vector<{c_type}> source_in{i}({size});", 4)
            out_str += format_str(f"for (int k = 0; k < {size}; k++) {{", 4)
            out_str += format_str(f"ifile{i} >> source_in{i}[k];", 8)
            out_str += format_str("}", 4)

    # Process outputs
    for i, (out_dtype, out_shape) in enumerate(outputs):
        size = np.prod(out_shape) if len(out_shape) > 0 else 1
        out_str += format_str(
            f"vector<{ctype_map.get(str(out_dtype), 'int')}> source_out{i}({size}, 0);",
            4,
        )

    out_str += "\n"

    # Call the top function
    # Note: signatures in Catapult HLS generated code generally match what we emitted.
    # Arrays are pointers or ac_channel references.
    # Scalars are values.
    # We need to construct the call arguments.

    args = []

    # Inputs
    for i, (in_dtype, in_shape) in enumerate(inputs):
        if len(in_shape) == 0:
            args.append(f"source_in{i}")
        else:
            args.append(f"source_in{i}.data()")

    # Outputs
    for i in range(len(outputs)):
        args.append(f"source_out{i}.data()")

    # Handling explicit return vs output arguments handled in `inputs` (legacy)
    # If num_output_args > 0, some inputs are actually outputs (pointers)
    # The logic in Vitis handles this.

    # Call kernel
    out_str += format_str(f"{top}({', '.join(args)});", 4)
    out_str += "\n"

    # Write outputs to files
    if len(outputs) > 0:
        for i, (_, out_shape) in enumerate(outputs):
            out_str += format_str(f'ofstream ofile{i}("output{i}.data");', 4)
            out_str += format_str(f"if (!ofile{i}) {{", 4)
            out_str += format_str(
                f'cerr << "Failed to open output file {i}!" << endl;', 8
            )
            out_str += format_str("return 1;", 8)
            out_str += format_str("}", 4)
            size = np.prod(out_shape) if len(out_shape) > 0 else 1
            out_str += format_str(f"for (int k = 0; k < {size}; k++) {{", 4)
            out_str += format_str(f"ofile{i} << source_out{i}[k] << endl;", 8)
            out_str += format_str("}", 4)
            out_str += format_str(f"ofile{i}.close();", 4)

    out_str += format_str("return 0;", 4)
    out_str += "}\n"

    return out_str



# Device strings that belong to an FPGA flow, not to Catapult.
#
# `configs["device"]` means different things to different backends: for vitis_hls it is an
# FPGA PART (u280, xcu250-...), for Catapult it is an ASIC STANDARD-CELL LIBRARY
# (nangate-45nm_beh, sky130). A script that supports both backends typically has one
# `--device` flag and forwards it to whichever it was asked for, so an FPGA part reaches
# this flow whenever the systemc/catapult path is taken with the FPGA default still set.
#
# The generator below passes any unrecognised device straight through as
# `solution library add <device>`, so that mistake used to surface only as Catapult's
#   "Could not locate library file for library name u280 for current configuration"
# from inside a csyn run -- with nothing pointing at the actual cause. Catch it here.
#
# DELIBERATELY A BLACKLIST, NOT A WHITELIST: a custom or site-specific ASIC library is a
# legitimate value we must keep passing through untouched. Only patterns that can ONLY be
# an FPGA are rejected.
_FPGA_DEVICE_PATTERNS = (
    "u200", "u250", "u280", "u50", "u55",          # AMD/Xilinx Alveo boards
    "xcu", "xc7", "xcvu", "xczu", "xcku", "xcau",  # Xilinx part prefixes
    "versal", "zynq", "kintex", "virtex", "artix", "spartan",
    "arria", "stratix", "cyclone", "agilex",       # Intel/Altera families
)


def _looks_like_fpga(device):
    d = str(device).lower()
    return any(p in d for p in _FPGA_DEVICE_PATTERNS)


def resolve_library(configs):
    """Pick the Catapult standard-cell library, from `library` or legacy `device`.

    `library` is the canonical key: what this flow selects IS a library
    (`solution library add <name>`), and calling it `device` invited exactly the bug
    this resolves -- one shared `--device` flag meaning an FPGA part to vitis_hls and a
    cell library here.

    Resolution order, chosen so a script that drives BOTH backends can be fixed by ADDING
    one key rather than restructuring what it passes:

      1. `library` given            -> use it; any `device` present belongs to the other
                                       backend and is ignored.
      2. no `library`, `device` given:
           - an FPGA part           -> ERROR. Nothing sensible to select, and silently
                                       defaulting would hand back an area number measured
                                       against a library the caller never chose.
           - anything else          -> use it (back-compat, incl. custom ASIC libraries).
      3. neither                    -> the default.
    """
    library = configs.get("library")
    if library is not None:
        return library
    device = configs.get("device")
    if device is None:
        return "nangate-45nm_beh"
    if not _looks_like_fpga(device):
        return device  # legacy spelling of `library`
    raise ValueError(
        f"device={device!r} is an FPGA part, but the Catapult/SystemC flow synthesizes to "
        f"an ASIC standard-cell library (e.g. 'nangate-45nm_beh' or 'sky130'). Catapult has "
        f"no such library and would fail later with "
        f"\"Could not locate library file for library name {device}\".\n"
        f"If one script drives both backends, the smallest fix is to ADD a 'library' key "
        f"for this flow -- configs={{'library': 'nangate-45nm_beh', 'device': {device!r}}} "
        f"-- since 'library' wins and 'device' is then left for target='vitis_hls'. "
        f"Dropping 'device' from the systemc configs works too (it defaults to "
        f"'nangate-45nm_beh')."
    )


# The caveat that must travel with every number this flow reports. A power figure
# without it is not usable evidence: it says what was measured and how.
PPA_ACTIVITY_CAVEAT = (
    "Power is measured from SAIF switching activity produced by simulating the C++ "
    "testbench against the pre-power RTL (100% of primary inputs and flop outputs "
    "annotated; internal nets propagated by PowerPro, not simulated). It is therefore "
    "WORKLOAD-SPECIFIC -- only as representative as that testbench -- and PRE-LAYOUT: "
    "a wireload model, PowerPro's clock-tree model, no place-and-route parasitics."
)


def resolve_ncsim_root(configs=None):
    """Locate the Xcelium install that SCVerify drives for the switching simulation.

    NOT hardcoded to any site. `go switching` needs an event simulator, and the ONE
    measured working configuration drives Xcelium (`/SCVerify/USE_NCSIM true` +
    `/NCSim/NC_ROOT <root>`). Catapult's own default is QuestaSim, and pointing it at
    an install with no `vsim` is how a power step "succeeds" having simulated nothing
    -- so the root has to be a real directory before we emit a tcl that claims one.

    Resolution order (first hit wins):
      1. configs["ncsim_root"]
      2. $NC_ROOT / $XCELIUM_HOME / $CDS_INST_DIR
      3. the install root above `xrun` on PATH
    Raises ValueError when nothing resolves, rather than emitting a default path that
    only exists on one host OR an empty root that silently runs no simulation. On
    zhang-21 none of 1-3 are set, so the explicit config is the one that works.
    """
    import shutil

    configs = configs or {}
    # A blank or whitespace-only value is NOT a root. Treated as given it would emit
    # `/NCSim/NC_ROOT ` with nothing after it, which points Catapult at nothing and
    # produces the silent no-simulation failure this whole mode exists to prevent.
    cand = configs.get("ncsim_root")
    cand = cand.strip() if isinstance(cand, str) else cand
    if cand:
        # An EXPLICIT root is taken as given even when it does not exist here: the
        # project is often generated on a machine without the tools (ace-01) and run
        # on the licence host (zhang-21), and refusing would make that handoff
        # impossible. Discovery below still insists on a real directory.
        if not os.path.isdir(cand):
            print(
                f"[warn] configs['ncsim_root']={cand!r} is not a directory on this "
                f"host. Emitting it anyway -- it must exist wherever run.tcl runs."
            )
        return cand
    for var in ("NC_ROOT", "XCELIUM_HOME", "CDS_INST_DIR"):
        cand = os.environ.get(var)
        if cand and os.path.isdir(cand):
            return cand
    xrun = shutil.which("xrun")
    if xrun:
        root = os.path.dirname(os.path.dirname(os.path.realpath(xrun)))
        # Xcelium keeps its binaries under a platform subdirectory -- zhang-21 has
        # both `tools/bin` and `tools.lnx86/bin` -- and NC_ROOT wants the directory
        # ABOVE that, not `<root>/tools`. Guessing one level too deep would emit a
        # root that exists but holds no install: a wrong path, silently.
        base = os.path.basename(root)
        if base == "tools" or base.startswith("tools."):
            root = os.path.dirname(root)
        return root
    # NOTHING RESOLVED -> raise. Emitting the tcl with an empty (or guessed) NC_ROOT
    # would send Catapult looking at nothing, and a switching step that simulates
    # nothing still "succeeds" -- exactly the silent zero this mode exists to prevent.
    # MEASURED: on zhang-21, NC_ROOT, XCELIUM_HOME and CDS_INST_DIR are all unset and
    # `xrun` is not on PATH, so discovery finds nothing there and the explicit config
    # is what works. Hence it is named first.
    raise ValueError(
        "mode=\"ppa\" runs an RTL simulation to get switching activity, and no "
        "Xcelium install was found -- so nothing is emitted, because a tcl with an "
        "empty /NCSim/NC_ROOT simulates nothing and reports a power of zero.\n"
        "Pass it explicitly: configs={'ncsim_root': '<xcelium root>'}. That is what "
        "works on a host where none of the environment variables are set (zhang-21 is "
        "one: there the root is /opt/cadence/XCELIUM2403, whose binaries live under "
        "tools/bin and tools.lnx86/bin -- an EXAMPLE, not a default; no site's path is "
        "compiled in).\n"
        "Otherwise export NC_ROOT, XCELIUM_HOME or CDS_INST_DIR, or put `xrun` on "
        "PATH. Xcelium also needs its licence: export CDS_LIC_FILE.\n"
        "Catapult's default simulator is QuestaSim; this flow does not use it because "
        "a Questa install without `vsim` silently simulates nothing and yields a power "
        "number of zero (dev/records/catapult_handoff/zhang21_power_2026-09-24/)."
    )


def resolve_ppa_testbench(configs):
    """Return the C++ testbench file `mode="ppa"` will hand to SCVerify.

    THE constraint of this flow: a design with no testbench SCVerify can drive
    produces no activity, and PowerPro then reports zeros or a default-toggle guess --
    a wrong power number in the safe-looking direction. So this raises instead of
    letting the flow run.

    The testbench is a plain C++ file with `CCS_MAIN(...)` that calls
    `CCS_DESIGN(<top>)(...)` with representative stimulus; it is added to the solution
    with `-exclude true` so it is compiled for verification but never synthesized.
    """
    tb = configs.get("testbench")
    if not tb:
        raise ValueError(
            "mode=\"ppa\" needs a C++ testbench that SCVerify can drive.\n"
            "Power here is MEASURED from switching activity: `go switching` simulates "
            "the testbench against the pre-power RTL and converts the VCD to SAIF. "
            "With no testbench nothing is simulated, and PowerPro reports zeros or a "
            "default-toggle estimate -- a wrong number that looks safe. Failing here "
            "is deliberate.\n"
            "Pass configs={'testbench': '/path/to/tb.cpp'}: a file with CCS_MAIN(...) "
            "calling CCS_DESIGN(<top>)(...) over representative stimulus. The worked "
            "example is dev/records/catapult_handoff/zhang21_power_2026-09-24/"
            "mac_tb.cpp (200 transactions, 248.47 uW).\n"
            "NOTE the SystemC flow's emitted kernel.cpp does NOT count: its testbench "
            "is an sc_main, which SCVerify does not drive. Use mode=\"csyn\" if you "
            "want area and latency only."
        )
    tb = os.path.abspath(os.path.expanduser(tb))
    if not os.path.isfile(tb):
        raise ValueError(
            f"configs['testbench']={tb!r} does not exist. mode=\"ppa\" needs the "
            f"C++ SCVerify testbench file itself, not a directory or a target name."
        )
    return tb


def codegen_tcl(top, configs):
    """Generate TCL script for Catapult HLS synthesis.

    Generates a hierarchical synthesis flow that preserves module boundaries
    so that per-PE and per-interconnect area/power can be extracted from reports.
    """
    # Clock period in ns. `clock_period` takes precedence over `frequency` when given.
    #
    # WHY BOTH: the FPGA-oriented configs think in MHz, but an ASIC flow thinks in ns,
    # and the period is not merely a constraint here -- Catapult BAKES IT INTO THE
    # SCHEDULE (how many ops it packs per cycle), so it is the main knob for trading
    # timing against area. Deriving it from MHz forced the user to convert (2.0 ns =
    # frequency 500) and silently rounded to one decimal, which made periods like
    # 3.33 ns unreachable. `frequency` stays supported unchanged.
    if configs.get("clock_period") is not None:
        clock_period = float(configs["clock_period"])
    else:
        frequency = configs.get("frequency", 100)
        clock_period = 1000 / frequency
    # Render with 1 decimal when that is EXACT, else 3. Periods that were already exact
    # at 1 decimal (2.0, 4.0, 10.0 ...) regenerate a byte-identical run.tcl.
    # DELIBERATE SMALL CHANGE: a period that is not exact at 1 decimal now keeps its
    # digits -- frequency=300 emits 3.333 where it used to emit 3.3. The old value was
    # 1% TIGHTER than the requested frequency actually implies, i.e. it silently
    # over-constrained the schedule. Anyone re-running such a project may see a slightly
    # different (correct) schedule.
    clock_period_str = (
        f"{clock_period:.1f}"
        if abs(clock_period - round(clock_period, 1)) < 1e-9
        else f"{clock_period:.3f}"
    )
    mode = configs.get("mode", "csyn")
    platform = configs.get("platform", "catapult")
    # `library` is the canonical key; `device` still accepted (see resolve_library).
    device = resolve_library(configs)
    # preserve_hier=True keeps sub-function boundaries in RTL output,
    # enabling per-module area/power breakdown in area.rpt.
    preserve_hier = configs.get("preserve_hierarchy", True)
    # sub_funcs: list of sub-function names to synthesize as separate RTL blocks.
    # Using block synthesis avoids HIER-10/HIER-47 errors (channels cross hierarchical
    # boundaries when functions are blocks, not inlined into top).
    sub_funcs = configs.get("sub_funcs", [])

    out_str = """# Project root directory
set sfd [file dir [info script]]

# Create new solution
solution new -state initial
solution options defaults
solution options set /Input/CppStandard c++11
"""

    # -D_GLIBCXX_USE_CXX11_ABI=0 matches Catapult's pre-CXX11 libsystemc for the
    # g++ CSIM compile. OMIT it for csyn/ppa: synthesis doesn't need it (the EDG
    # front end ignores libstdc++ ABI), and Catapult's SCVerify RTL cosim forwards
    # this option to xmsc's g++ with the Tcl braces intact -> g++ sees `{-D...}` as
    # an input filename -> "output files may not be specified when compiling
    # several" -> the RTL compile dies. Gating it to csim lets Allo-generated
    # designs cosim (csyn project + SCVerify) without hand-editing the tcl.
    if mode == "csim":
        out_str += "solution options set /Input/CompilerFlags {{-D_GLIBCXX_USE_CXX11_ABI=0}}\n"

    # SCVerify RTL cosim: register the flow and pin it to Xcelium/ncsim BEFORE any
    # source is added, so `go extract` emits Verify_concat_sim_rtl_v_ncsim.mk -- the
    # makefile that reruns the emitted SystemC testbench against synthesized RTL for a
    # golden-vs-RTL bit-exact check. (USE_MSIM/USE_VCS off: this flow runs on Xcelium.)
    # Note: cosim deliberately does NOT set the -D..CXX11_ABI csim flag above; Catapult
    # forwards it to xmsc's RTL g++ with the Tcl braces intact and breaks that compile.
    if mode == "cosim":
        out_str += """flow package require /SCVerify
flow package option set /SCVerify/USE_NCSIM true
flow package option set /SCVerify/USE_MSIM false
flow package option set /SCVerify/USE_VCS false
"""

    # PPA: the power half of "PPA" is a MEASUREMENT, and these four lines are what
    # make it one. Every one of them was needed for the single run that produced real
    # numbers (dev/records/catapult_handoff/zhang21_power_2026-09-24/):
    #   * SCVerify + USE_NCSIM: `go switching` needs an event simulator to run the C++
    #     testbench against the pre-power RTL. Catapult defaults to QuestaSim; when
    #     that install has no `vsim` the step "succeeds" having simulated NOTHING, and
    #     the power report comes back all zeros. Hence an explicit, verified NC_ROOT.
    #   * SWITCHING_ACTIVITY_TYPE saif: the default is FSDB, which needs Verdi
    #     ($NOVAS_INST_DIR). SAIF goes through vcd2saif, which ships with the tools.
    # NC_ROOT is resolved from configs/env HERE, so the emitted tcl is host-specific
    # by construction while the backend hardcodes no site's paths.
    if mode == "ppa":
        ncsim_root = resolve_ncsim_root(configs)
        activity = configs.get("switching_activity_type", "saif")
        out_str += f"""flow package require /SCVerify
flow package option set /SCVerify/USE_QUESTASIM false
flow package option set /SCVerify/USE_NCSIM true
flow package require /NCSim
flow package option set /NCSim/NC_ROOT {ncsim_root}
flow package require /LowPower
flow package option set /LowPower/SWITCHING_ACTIVITY_TYPE {activity}
"""
        # USE_CCS_BLOCK is for designs marked with the CCS_BLOCK() macro. Allo emits
        # `#pragma hls_design top` instead, which SCVerify handles without it, so this
        # stays off unless the caller's own sources use the macro.
        if configs.get("use_ccs_block", False):
            out_str += "flow package option set /SCVerify/USE_CCS_BLOCK true\n"

    out_str += """
# Add source files
solution file add "$sfd/kernel.cpp" -type C++
"""

    # Only include host.cpp for csim mode. The systemc flow emits a self-contained
    # kernel.cpp with its own sc_main testbench, so it has NO separate host.cpp.
    if mode == "csim" and platform != "systemc":
        out_str += 'solution file add "$sfd/host.cpp" -type C++ -exclude true\n'

    # The SCVerify testbench for ppa. `-exclude true` = compiled for verification,
    # never synthesized. resolve_ppa_testbench raises when it is missing, so this is
    # the point at which a design with no testbench fails -- at build(), before any
    # licence is taken and long before a zero lands in a report.
    if mode == "ppa":
        tb_name = os.path.basename(resolve_ppa_testbench(configs))
        out_str += f'solution file add "$sfd/{tb_name}" -type C++ -exclude true\n'

    # synth_top: synthesize a SUBMODULE instead of the whole region.
    #
    # A @df.region() usually contains the design kernels AND testbench kernels -- the
    # injector/collector that own the host arrays -- plus the AlloMem memories backing
    # those arrays. Defaulting DESIGN_HIERARCHY to the region top means Catapult
    # synthesizes all of it, so any reported AREA includes the harness. Measured on a
    # 4-port wormhole router that was 5,806 um2 of 22,260 -- 26% -- which makes any
    # comparison against a reference whose top is the design alone badly misleading.
    #
    # Each kernel is emitted as its own SC_MODULE named <kernel>_0, with Connections::In/
    # Out ports bound to the region's channels, so it is a legal synthesis top by itself.
    #
    #     df.build(region, target="systemc", mode="csyn", synth_top="router_0")
    #
    # The testbench is NOT removed -- csim still drives the full region. Only what
    # Catapult treats as the top changes, so verification and measurement may differ:
    #   csim/cosim -> full region (drv/col supply and check the stimulus)
    #   area/Fmax  -> synth_top=<kernel>_0
    # NOTE cosim does NOT work against a submodule top: SCVerify wraps the design top and
    # the input<k>.data -> AlloMem stimulus path disappears. Run those separately.
    #
    # There is deliberately NO heuristic for "which kernels are the testbench". Excluding
    # kernels that take args would work for the common harness shape but is wrong in
    # general -- a real design's top kernel can legitimately own arrays.
    design_top = configs.get("synth_top") or top

    out_str += f"""
# Set top-level design function
directive set -DESIGN_HIERARCHY {design_top}

# Set clock constraints
directive set -CLOCKS {{clk {{-CLOCK_PERIOD {clock_period_str}}}}}

# Set output language
solution options set /Output/OutputVerilog true
solution options set /Output/OutputVHDL false
"""

    # Connections (MatchLib) designs write several non-blocking handshakes per
    # SC_THREAD body (every NoC router does). Catapult's DEFAULT -IO_MODE fixed
    # pins each port's vld/dat to a fixed cycle offset, so N-per-body collide ->
    # SCHD-67/SCHD-30 ("could not schedule even with unlimited resources"). This
    # is exactly matchlib's own required setting (hls/run_hls_global_setup.tcl):
    # -IO_MODE super lets the scheduler place each handshake within the loop
    # window, and -SPECULATE true covers the conditional pushes. Verified: the
    # whole Channel router (38 PushNB + 38 PopNB) csynths clean with these two.
    if platform == "systemc":
        out_str += """
directive set -IO_MODE super
directive set -SPECULATE true
"""

    # Library selection based on device
    if "45nm" in device or "nangate" in device:
        out_str += "solution library add nangate-45nm_beh\n"
    elif "sky130" in device:
        out_str += "solution library add sky130\n"
    else:
        out_str += f"solution library add {device}\n"

    out_str += """
# Flow
go analyze
"""

    # Block synthesis: keep sub-functions as separate RTL modules so channels
    # cross hierarchical boundaries (avoids HIER-10/HIER-47 errors).
    if sub_funcs:
        for fn in sub_funcs:
            out_str += f"solution design set {fn} -block\n"
        out_str += "\n"

    out_str += "go compile\n"


    if mode == "csim":
        # NOTE: `solution app linkage/execution` was removed in Catapult 2024.2
        # (`solution` has no `app` operator). Catapult's own csim now goes through
        # SCVerify (`flow run /SCVerify/launch_make .../Verify_orig_cxx_osci.mk
        # SIMTOOL=osci sim`), which requires CCS_DESIGN-wrapped DUTs. The systemc
        # flow instead emits a self-contained plain-sc_main kernel.cpp, run
        # directly via the generated `csim.sh` (g++ + $MGC_HOME libsystemc). The
        # `go compile` above still validates HLS synthesis.
        if platform != "systemc":
            out_str += """
solution app linkage
solution app execution
"""

    # Continue synthesis if not just csim. cosim needs full synthesis + `go extract`
    # (that is what generates the SCVerify RTL-cosim makefile), so it runs here too.
    if mode in {"csyn", "ppa", "cosim"}:
        out_str += """
solution library add ccs_sample_mem
go assembly
"""
        out_str += "go extract\n"

    # csyn stops at `go extract`. Power needs two more steps, and mode="ppa" used to
    # emit neither -- which is why it was documented as producing power and produced
    # none. `go switching` runs SCVerify (testbench vs pre-power RTL) and writes
    # <sol>/switching_v/test.saif; report_pre_pwropt_Verilog annotates that SAIF onto
    # the netlist and writes <sol>/power.rpt.
    if mode == "ppa":
        out_str += """
# Power: annotate simulated activity, then report
directive set USE_MODES {test}
directive set /USE_MODES/test/PWR_CLOCK_MODE {{clk default}}
directive set /USE_MODES/test/PWR_OPT_WEIGHT 1.0
go switching
flow run /PowerAnalysis/report_pre_pwropt_Verilog
"""

    out_str += "\nexit\n"
    return out_str


_PWR_ROW = re.compile(
    r"^(\s+)(Static|Dynamic|Total)((?:\s+-?[\d.]+){5})\s*$"
)
_PWR_COLS = ("memory", "register", "combinational", "clock_network", "total")


def parse_power_report(power_rpt):
    """Parse Catapult/PowerPro's ``power.rpt`` (the real table format).

    The previous parser looked for ``Total Power:``. NO SUCH STRING EXISTS in the
    report PowerPro writes, so `mode="ppa"` printed ``N/A`` even after a successful
    power run. The real shape (see
    dev/records/catapult_handoff/zhang21_power_2026-09-24/power.rpt) is::

        Switching Activity (Percent Asserted)
          Use Mode                Flop Outputs User Nets
          ----------------------- ------------ ---------
          pre_pwropt_test_Verilog       100.00    100.00

        Power Report (uW)
                                     Memory Register Combinational Clock Network  Total
          pre_pwropt_test_Verilog
            Static                     0.00     4.42         14.27          0.10  18.80
            Dynamic                    0.00    61.78        147.96         19.93 229.67
            Total                      0.00    66.20        162.23         20.03 248.47

            mac_core_inst
              Static                   ...

    The first (least-indented) block is the whole design; deeper ones are instances.
    All figures are microwatts.

    Returns ``None`` when the file does not exist or contains no power table, else::

        {"use_mode": str, "unit": "uW",
         "static"/"dynamic"/"total": {memory, register, combinational,
                                      clock_network, total},
         "annotation": {"flop_outputs_pct": float, "user_nets_pct": float},
         "instances": {name: {"static": f, "dynamic": f, "total": f}}}
    """
    if not os.path.exists(power_rpt):
        return None
    with open(power_rpt, "r") as f:
        text = f.read()

    head, _, body = text.partition("Power Report")
    if not body:
        return None
    # drop the rest of the "Power Report (uW)" title line, else "(uW)" reads as a block
    body = body.split("\n", 1)[1] if "\n" in body else ""
    body = body.split("End of Report")[0]

    res = {"unit": "uW", "use_mode": None, "instances": {}, "annotation": {}}
    design = {}
    blocks = {}          # name -> {"Static": [...], ...}
    order = []
    current = None
    base_indent = None
    for line in body.splitlines():
        m = _PWR_ROW.match(line)
        if m:
            if current is None:
                continue
            vals = [float(x) for x in m.group(3).split()]
            blocks[current][m.group(2)] = dict(zip(_PWR_COLS, vals))
            continue
        stripped = line.strip()
        if not stripped or set(stripped) <= set("- "):
            continue
        # The column header, not a block name.
        if "Memory" in line and "Combinational" in line:
            continue
        indent = len(line) - len(line.lstrip())
        if base_indent is None:
            base_indent = indent
        if indent < base_indent:
            continue
        current = stripped
        blocks.setdefault(current, {})
        order.append((indent, current))

    if not order:
        return None
    top_indent, top_name = order[0]
    res["use_mode"] = top_name
    design = blocks.get(top_name, {})
    for key in ("Static", "Dynamic", "Total"):
        if key in design:
            res[key.lower()] = design[key]
    if "total" not in res:
        return None
    for indent, name in order[1:]:
        if indent <= top_indent:
            continue
        rows = blocks.get(name, {})
        res["instances"][name] = {
            k.lower(): v["total"] for k, v in rows.items() if "total" in v
        }

    # Annotation coverage: how much of the netlist the SAIF actually pinned down.
    # 100/100 is what a real simulation gives; anything less (or a missing row) means
    # the number leans on propagation or defaults.
    m = re.search(
        r"Switching Activity.*?^\s*"
        + re.escape(top_name)
        + r"\s+([\d.]+)\s+([\d.]+)\s*$",
        head + "Power Report",
        re.S | re.M,
    )
    if m:
        res["annotation"] = {
            "flop_outputs_pct": float(m.group(1)),
            "user_nets_pct": float(m.group(2)),
        }
    return res


def assert_power_measured(sol_dir):
    """Return the parsed power report, or raise saying exactly what went wrong.

    A silent zero here is worse than a crash: it is a power number that is wrong in
    the safe-looking direction. So every way the flow can "succeed" without measuring
    anything -- no report, no table, no switching activity -- is turned into a loud
    failure that names the likely cause.
    """
    power_rpt = os.path.join(sol_dir, "power.rpt")
    pwr = parse_power_report(power_rpt)
    if pwr is None:
        raise RuntimeError(
            f"ppa: no usable power report at {power_rpt}. The flow ran but produced "
            f"no power table. Check the Catapult log for the `go switching` step: if "
            f"SCVerify could not launch the simulator (Catapult defaults to QuestaSim "
            f"and reports `No rule to make target .../modelsim.ini`), nothing was "
            f"simulated. Xcelium needs NC_ROOT (configs['ncsim_root']) and a licence "
            f"in CDS_LIC_FILE."
        )
    dyn = pwr.get("dynamic", {}).get("total", 0.0)
    if not dyn:
        raise RuntimeError(
            f"ppa: {power_rpt} reports ZERO dynamic power, which means the switching "
            f"simulation produced no activity -- the testbench did not drive the "
            f"design, or the SAIF was empty. The number is not a measurement; "
            f"refusing to report it."
        )
    ann = pwr.get("annotation", {})
    if ann and min(ann.values()) <= 0.0:
        raise RuntimeError(
            f"ppa: {power_rpt} shows 0% switching-activity annotation "
            f"({ann}); the SAIF annotated nothing, so the figures are default-toggle "
            f"estimates, not a measurement."
        )
    return pwr


def parse_catapult_report(project_path, top):
    """Parse Catapult HLS synthesis report (flat summary).

    Parameters
    ----------
    project_path : str
        Path to the project directory
    top : str
        Top-level function name

    Returns
    -------
    dict
        Parsed metrics (Area, Latency, Power).
    """

    sol_dir = os.path.join(project_path, "Catapult", f"{top}.v1")

    res = {
        "Latency (cycles)": "N/A",
        "Area": "N/A",
        "Power": "N/A",
    }

    # --- Latency from cycle.rpt ---
    cycle_rpt = os.path.join(sol_dir, "cycle.rpt")
    if not os.path.exists(cycle_rpt):
        cycle_rpt = os.path.join(project_path, f"{top}.rpt")

    if os.path.exists(cycle_rpt):
        with open(cycle_rpt, "r") as f:
            content = f.read()
        m = re.search(r"Max Latency\s*:\s*(\d+)", content)
        if m:
            res["Latency (cycles)"] = m.group(1)
        else:
            # hierarchical (SystemC) cycle.rpt: per-process rows
            #   /top/<kernel>/run  <ops> <latency> <throughput> ...
            lats = [int(x) for x in re.findall(r"/run\s+\d+\s+(\d+)\s+\d+", content)]
            if lats:
                res["Latency (cycles)"] = str(max(lats))
            else:
                # Function-flow cycle.rpt: one "Design Total:" row, columns
                #   <ops> <latency> <throughput> <reset length> <II>
                # A NEGATIVE latency is not a parse failure and not an error: a
                # free-running SC_THREAD has no first-output latency, and Catapult
                # writes -1. Say so rather than hiding it behind "N/A".
                m = re.search(r"Design Total:\s+\d+\s+(-?\d+)\s+(-?\d+)", content)
                if m:
                    lat = int(m.group(1))
                    res["Latency (cycles)"] = (
                        str(lat) if lat >= 0 else f"{lat} (free-running)"
                    )
                    res["Throughput (II)"] = m.group(2)

    # --- Area from area.rpt (function backend) or rtl.rpt (SystemC flow) ---
    area_rpt = os.path.join(sol_dir, "area.rpt")
    if os.path.exists(area_rpt):
        with open(area_rpt, "r") as f:
            area_content = f.read()
        m = re.search(r"Total Area\s*:\s*([\d\.]+)", area_content)
        if m:
            res["Area"] = m.group(1)
    else:
        rtl_rpt = os.path.join(sol_dir, "rtl.rpt")
        if os.path.exists(rtl_rpt):
            with open(rtl_rpt, "r") as f:
                area_content = f.read()
            m = re.search(r"TOTAL AREA \(After Assignment\):\s*([\d\.]+)", area_content)
            if m:
                res["Area"] = m.group(1)

    # --- Power from power.rpt (PowerPro's table; see parse_power_report) ---
    pwr = parse_power_report(os.path.join(sol_dir, "power.rpt"))
    if pwr is not None:
        unit = pwr["unit"]
        res["Power"] = f"{pwr['total']['total']:.2f} {unit}"
        res["Power dynamic"] = f"{pwr['dynamic']['total']:.2f} {unit}"
        res["Power static"] = f"{pwr['static']['total']:.2f} {unit}"
        res["Power clock net"] = f"{pwr['total']['clock_network']:.2f} {unit}"
        ann = pwr.get("annotation")
        if ann:
            res["SAIF annotated"] = (
                f"{ann['flop_outputs_pct']:.0f}% flops / "
                f"{ann['user_nets_pct']:.0f}% nets"
            )
        res["_power"] = pwr

    return res


def parse_catapult_hierarchical_report(project_path, top):
    """Parse Catapult HLS area.rpt for per-module (hierarchical) PPA breakdown.

    Catapult writes a hierarchical area report when -PRESERVE_HIERARCHY is set.
    The report has indented module entries like:

        Module: memory_tile_2x1
          Cell Area   : 1234.56
          ...
        Module: compute_tile_2x1
          Cell Area   : 567.89

    Returns
    -------
    dict
        {
          "top": {"area": float, "cells": int},          # entire design
          "modules": {
              "<func_name>": {"area": float, "cells": int},
              ...
          },
          "summary": str,   # human-readable table
        }
    """
    sol_dir = os.path.join(project_path, "Catapult", f"{top}.v1")
    area_rpt = os.path.join(sol_dir, "area.rpt")

    result = {"top": {}, "modules": {}, "summary": "No area.rpt found."}
    if not os.path.exists(area_rpt):
        # Catapult writes no area.rpt in this flow -- area lives in rtl.rpt, which has
        # no per-module rows. power.rpt DOES carry a per-instance breakdown, so when a
        # ppa run produced one, report that instead of an empty table.
        pwr = parse_power_report(os.path.join(sol_dir, "power.rpt"))
        if pwr is None:
            return result
        unit = pwr["unit"]
        lines = [
            f"Per-instance power ({unit}) -- {pwr['use_mode']}",
            "=" * 64,
            f"{'Instance':<40} {'Total':>10} {'Dynamic':>10}",
            "-" * 64,
            f"{'[TOP] ' + top:<40} {pwr['total']['total']:>10.2f} "
            f"{pwr['dynamic']['total']:>10.2f}",
        ]
        for name, vals in pwr["instances"].items():
            lines.append(
                f"  {name:<38} {vals.get('total', float('nan')):>10.2f} "
                f"{vals.get('dynamic', float('nan')):>10.2f}"
            )
        lines += ["-" * 64, PPA_ACTIVITY_CAVEAT]
        result["modules"] = {
            k: {"power": v.get("total")} for k, v in pwr["instances"].items()
        }
        result["top"] = {"power": pwr["total"]["total"]}
        result["summary"] = "\n".join(lines)
        return result

    with open(area_rpt, "r") as f:
        content = f.read()

    # --- Top-level total ---
    m = re.search(r"Total Area\s*:\s*([\d\.]+)", content)
    if m:
        result["top"]["area"] = float(m.group(1))
    m = re.search(r"Total Cells\s*:\s*(\d+)", content)
    if m:
        result["top"]["cells"] = int(m.group(1))

    # --- Per-module breakdown ---
    # Catapult area.rpt format (approximate):
    #   Module: <name>
    #     Cell Area   : <value>
    #     Cell Count  : <value>
    #     Power       : <value>  (optional)
    module_blocks = re.findall(
        r"Module:\s*(\S+)(.*?)(?=Module:|\Z)", content, re.DOTALL
    )
    for mod_name, block in module_blocks:
        info = {}
        a = re.search(r"Cell Area\s*:\s*([\d\.]+)", block)
        if a:
            info["area"] = float(a.group(1))
        c = re.search(r"Cell Count\s*:\s*(\d+)", block)
        if c:
            info["cells"] = int(c.group(1))
        p = re.search(r"Power\s*:\s*([\d\.eE\+\-]+)", block)
        if p:
            info["power"] = float(p.group(1))
        if info:
            result["modules"][mod_name] = info

    # --- Human-readable summary table ---
    lines = ["Hierarchical PPA Report (Catapult HLS)", "=" * 60]
    top_area = result["top"].get("area", "N/A")
    lines.append(f"{'Module':<35} {'Area':>10} {'Cells':>8}")
    lines.append("-" * 60)
    lines.append(
        f"{'[TOP] ' + top:<35} {str(top_area):>10} "
        f"{str(result['top'].get('cells', 'N/A')):>8}"
    )
    for mod, info in result["modules"].items():
        lines.append(
            f"  {mod:<33} {str(info.get('area', 'N/A')):>10} "
            f"{str(info.get('cells', 'N/A')):>8}"
        )

    # Infer interconnect cost = top - sum(compute modules)
    module_area_sum = sum(
        v.get("area", 0) for v in result["modules"].values()
    )
    if isinstance(top_area, float) and module_area_sum > 0:
        interconnect = top_area - module_area_sum
        lines.append("-" * 60)
        lines.append(
            f"  {'[Interconnect/Overhead]':<33} {interconnect:>10.2f} {'':>8}"
        )

    result["summary"] = "\n".join(lines)
    return result
